<?php
declare(strict_types=1);
require_once __DIR__."/db.php";require_once __DIR__."/funktionen.php";require_once __DIR__."/rechnung_funktionen.php";require_once __DIR__."/zahlungs_service.php";
$auftragId=positive_id($_GET["auftrag_id"]??($_POST["auftrag_id"]??null),"Auftrag");$fehler=null;
if($_SERVER["REQUEST_METHOD"]==="POST"){try{csrf_pruefen($_POST["csrf_token"]??null);berechtigung_pruefen(["administrator","mitarbeiter"]);altzahlung_zuordnen($pdo,$auftragId,$_POST["verteilung"]??[]);flash_setzen("success","Die ältere Zahlung wurde vollständig und nachvollziehbar zugeordnet.");weiterleiten("bearbeiten.php?id=".$auftragId);}catch(EingabeException $e){$fehler=$e->getMessage();}}
$auftrag=auftrag_fuer_druck_laden($pdo,$auftragId);if((float)$auftrag["nicht_zugeordnet_bezahlt"]<=0){flash_setzen("success","Für diesen Auftrag ist keine ältere Zahlung mehr zuzuordnen.");weiterleiten("bearbeiten.php?id=".$auftragId);}
?>
<!DOCTYPE html><html lang="de"><head><link rel="icon" href="favicon.svg" type="image/svg+xml"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alte Zahlung zuordnen</title><link rel="stylesheet" href="styles.css"></head><body><main class="app-shell"><div class="page-heading"><div><p class="eyebrow">Einmalige Zuordnung</p><h1><?= betrag_anzeigen($auftrag["nicht_zugeordnet_bezahlt"]) ?> auf Geräte verteilen</h1></div></div><?php if($fehler):?><div class="notice notice--error"><?= h($fehler) ?></div><?php endif;?><form class="glass-panel form-card form-layout" method="post"><?= csrf_feld() ?><input type="hidden" name="auftrag_id" value="<?= h($auftragId) ?>"><p>Die Summe muss exakt dem vorhandenen Betrag entsprechen. Keine Zahlung wird gelöscht.</p><?php foreach($auftrag["geraete"] as $g):?><div class="form-field"><label><?= h($g["referenz"]." · ".$g["geraetetyp"]) ?> (offen <?= betrag_anzeigen($g["restbetrag"]) ?>)</label><div class="input-suffix"><input name="verteilung[<?= h($g["zuordnung_id"]) ?>]" value="0,00" inputmode="decimal" pattern="[0-9]{1,8}([,.][0-9]{1,2})?" required><span>€</span></div></div><?php endforeach;?><div class="form-actions"><a class="button button--secondary" href="bearbeiten.php?id=<?= h($auftragId) ?>">Abbrechen</a><button class="button button--primary">Zuordnung verbindlich bestätigen</button></div></form></main></body></html>
